-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Tolerable misstatement threshold in audit sampling
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redfield Electronics, the auditor sets tolerable misstatement at $50,000 for inventory testing. The projected misstatement from sampling is $47,000, with an additional $5,000 in known misstatements from other tests. The auditor should conclude that:', '["The combined misstatements suggest the account may be materially misstated and additional procedures are needed", "The tolerable misstatement was not exceeded because only the projected amount counts", "The known misstatements should be ignored since sampling already accounts for them", "The auditor must issue a qualified opinion based on the inventory balance"]'::jsonb, 0, 'Under AU-C 450, the auditor evaluates the aggregate effect of all identified misstatements, including both projected misstatements from sampling and known misstatements from other procedures. When the combined total ($52,000) exceeds tolerable misstatement ($50,000), additional procedures are warranted. Option B is incorrect because known misstatements from non-sampling procedures must be added to projected misstatements for a complete evaluation.', 'medium', 2),

-- Q2: easy / L1 — Definition of clearly trivial misstatement
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, a "clearly trivial" misstatement is best described as:', '["A misstatement below the amount the auditor posted to the summary of uncorrected misstatements", "A misstatement that is individually and in aggregate clearly inconsequential to the financial statements", "Any misstatement below 5% of the relevant account balance", "A misstatement that management has agreed to correct before year-end"]'::jsonb, 1, 'AU-C 450.A2 defines clearly trivial misstatements as those that are clearly inconsequential, whether taken individually or in the aggregate. The auditor need not accumulate such amounts on the summary of uncorrected misstatements. Option A is incorrect because the threshold is based on whether misstatements are inconsequential, not on an arbitrary posting threshold.', 'easy', 1),

-- Q3: medium / L3 — Evaluating a pattern of misstatements suggesting management bias
(1, 'Misstatements and Control Deficiencies', 'While auditing Granite Peak Hospitality, the auditor notices that all eight uncorrected misstatements in revenue accounts overstate revenue, while no misstatements understate revenue. Each individual misstatement is below clearly trivial, but they total $38,000 against materiality of $200,000. The auditor should:', '["Accept the misstatements as clearly trivial since each is below the threshold", "Request management correct at least half the misstatements to eliminate the pattern", "Consider whether the one-directional pattern indicates a possible bias in management''s financial reporting", "Issue a qualified opinion because the directional pattern invalidates the sampling results"]'::jsonb, 2, 'AU-C 450.11 requires the auditor to consider whether uncorrected misstatements indicate a bias in management''s financial reporting. A consistent one-directional pattern—all overstating revenue—may signal intentional bias even when individual amounts are immaterial. Option A is incorrect because the directional consistency elevates the concern beyond the trivial threshold of any single item.', 'medium', 3),

-- Q4: easy / L1 — Recipients of control deficiency communications in nonissuer audit
(1, 'Misstatements and Control Deficiencies', 'In a nonissuer audit, to whom must the auditor communicate material weaknesses in writing under AU-C 265?', '["The external audit regulator and the SEC", "Management and the entity''s legal counsel", "The shareholders at the next annual meeting", "Those charged with governance and management"]'::jsonb, 3, 'AU-C 265.09 requires the auditor to communicate in writing to those charged with governance all significant deficiencies and material weaknesses identified during the audit. AU-C 265.10 further requires communication to management of material weaknesses. Option B is incorrect because legal counsel is not a required recipient of control deficiency communications under auditing standards.', 'easy', 1),

-- Q5: medium / L2 — Misstatement arising from management override of controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Distributors, the auditor discovers that the CFO manually overrode the automated three-way match control to process a $120,000 payment to a vendor without a purchase order. The payment was for legitimate consulting services. Under AU-C 240, this situation most directly represents:', '["A misstatement arising from management override that requires further investigation regardless of legitimacy", "A routine business transaction that needs no additional audit attention", "A significant deficiency that the auditor should communicate only to management", "Evidence of fraud that must be reported to law enforcement"]'::jsonb, 0, 'AU-C 240.31 requires the auditor to design procedures to address the risk of management override of controls, regardless of the auditor''s assessment of fraud risk. Even when a transaction appears legitimate, manual override of automated controls warrants investigation. Option B is incorrect because management override always requires further scrutiny under AU-C 240, even when the underlying transaction appears proper.', 'medium', 2),

-- Q6: medium / L2 — Likelihood dimension in classifying control deficiencies
(1, 'Misstatements and Control Deficiencies', 'While auditing Silverstone Manufacturing, the auditor identifies a control deficiency in the payroll department where overtime calculations are manually entered without supervisory review. No misstatements have been detected to date. Under AU-C 265, the auditor should classify the severity of this deficiency primarily by evaluating:', '["Whether the control has actually failed during the current year", "The likelihood that the deficiency could result in a misstatement and the magnitude of the potential misstatement", "The number of employees affected by the overtime calculation process", "Whether management has plans to implement an automated overtime system"]'::jsonb, 1, 'AU-C 265.A7 states that the severity of a control deficiency depends on the magnitude of potential misstatement and the likelihood that a misstatement could occur. Both dimensions must be assessed regardless of whether an actual misstatement has been detected. Option A is incorrect because classification depends on the potential for misstatement, not only on whether a failure has already occurred.', 'medium', 2),

-- Q7: medium / L3 — Cascading control failures across multiple accounts
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Construction, the auditor discovers that the general ledger account reconciliation process has no independent review for any balance sheet account. This single deficiency affects cash, receivables, payables, and fixed assets. When evaluating severity under AU-C 265, the auditor should:', '["Evaluate the deficiency separately for each account and report the worst classification", "Assess the deficiency only for the largest account balance affected", "Consider the combined magnitude of potential misstatement across all affected accounts when determining severity", "Report the deficiency as a significant deficiency regardless of magnitude since it affects multiple accounts"]'::jsonb, 2, 'Under AU-C 265.A8, when a single control deficiency affects multiple financial statement accounts, the auditor considers the aggregate magnitude of potential misstatements across all affected accounts. The combined exposure may elevate a deficiency to material weakness even if no single account exceeds materiality. Option A is incorrect because the deficiency is evaluated holistically, not separately for each account.', 'medium', 3),

-- Q8: easy / L1 — Definition of pervasive in context of misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 705, a misstatement is considered "pervasive" to the financial statements when it:', '["Exceeds the overall materiality threshold by more than 50%", "Was caused by intentional fraud rather than error", "Is confined to a single disclosure but involves a related party", "Is not confined to specific elements and represents a substantial proportion of the financial statements"]'::jsonb, 3, 'AU-C 705.A1 defines pervasive effects as those not confined to specific elements, accounts, or items of the financial statements, or if confined, represent a substantial proportion of the financial statements. Pervasiveness determines whether a qualified or adverse opinion is appropriate. Option A is incorrect because pervasiveness relates to the breadth of impact, not solely to the magnitude relative to materiality.', 'easy', 1),

-- Q9: easy / L1 — Timing of material weakness communications
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, written communication of significant deficiencies and material weaknesses to those charged with governance should be made:', '["Within 30 calendar days of the deficiency being identified", "Immediately upon identification, before continuing fieldwork", "No later than 60 days after the report release date", "No later than 60 days after the report release date, or sooner if required by other agreements"]'::jsonb, 2, 'AU-C 265.12 requires that the written communication of significant deficiencies and material weaknesses be made no later than 60 days following the report release date. Engagements may specify earlier deadlines by agreement. Option B is incorrect because while timely communication is encouraged, the standard establishes the 60-day post-release deadline for the formal written communication.', 'easy', 1),

-- Q10: medium / L3 — Segregation of duties deficiency assessment using magnitude and likelihood
(1, 'Misstatements and Control Deficiencies', 'During the audit of Briarwood Pharmaceuticals, the auditor finds that the accounts payable clerk can both create new vendors and approve invoices for payment. Monthly disbursements total $4.2 million, and materiality is $300,000. No fraudulent transactions have been identified. The auditor should classify this as:', '["A control deficiency only, since no actual misstatement has occurred", "A significant deficiency because the lack of segregation creates moderate risk", "An operational matter outside the scope of the financial statement audit", "A material weakness because the magnitude of transactions processed through the deficient control is significant relative to materiality"]'::jsonb, 3, 'Under AU-C 265.A7, the auditor assesses both magnitude and likelihood. A segregation of duties failure where one person controls vendor creation and invoice approval over $4.2 million monthly creates a reasonably possible risk of material misstatement well exceeding the $300,000 materiality. Option B is incorrect because the combination of high magnitude and reasonable possibility elevates this beyond a significant deficiency to a material weakness.', 'medium', 3),

-- Q11: hard / L4 — Evaluating opinion modification when uncorrected misstatements approach materiality
(1, 'Misstatements and Control Deficiencies', 'The auditor of Westbrook Financial Corp. has identified $180,000 in uncorrected misstatements, including $95,000 in projected misstatements and $85,000 in known misstatements. Overall materiality is $200,000 and performance materiality is $150,000. Management refuses to make corrections. All misstatements overstate net income. The auditor determines that additional procedures cannot further reduce audit risk. The most appropriate course of action is to:', '["Issue an unmodified opinion since total uncorrected misstatements are below overall materiality", "Request management to provide a written representation that the misstatements are immaterial", "Issue a qualified opinion because the uncorrected misstatements are material to the financial statements when considering their one-directional nature and proximity to materiality", "Withdraw from the engagement because management''s refusal indicates a scope limitation"]'::jsonb, 2, 'Under AU-C 450.11 and AU-C 705, the auditor considers qualitative factors alongside quantitative thresholds. The one-directional overstatement pattern suggesting bias (AU-C 450.A22), proximity to materiality ($180,000 vs. $200,000), and exceedance of performance materiality ($150,000) collectively warrant a qualified opinion. Option A is incorrect because materiality is not a bright-line threshold—qualitative factors such as directional bias can render amounts below the quantitative threshold material.', 'hard', 4),

-- Q12: medium / L3 — Applying reasonable possibility threshold to an IT control gap
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Software Inc., the auditor discovers that database administrator access logs are not reviewed, meaning unauthorized changes to financial data could go undetected. The company processes 50,000 transactions monthly through the database. IT management states that no unauthorized changes have been reported. Under AU-C 265, the auditor should evaluate this deficiency by:', '["Accepting IT management''s assertion as sufficient evidence that the control is operating effectively", "Assessing whether there is a reasonable possibility that the lack of log review could result in a material misstatement, considering the volume and nature of transactions processed", "Classifying the deficiency as a significant deficiency because IT controls are inherently less critical than manual controls", "Deferring evaluation until the next audit cycle to determine if any unauthorized changes actually occur"]'::jsonb, 1, 'Under AU-C 265.A6, the auditor evaluates whether a reasonable possibility exists that the deficiency could result in a material misstatement. With 50,000 monthly transactions and no detective control over database changes, the potential magnitude is significant. Option A is incorrect because management''s assertion alone does not constitute sufficient evidence to evaluate a control deficiency''s severity.', 'medium', 3),

-- Q13: medium / L2 — Known vs. likely misstatement classification from sampling
(1, 'Misstatements and Control Deficiencies', 'While testing accounts receivable for Oakdale Retail Group, the auditor confirms a sample of 40 accounts from a population of 1,200. Three confirmations reveal pricing errors totaling $6,200. The auditor corrects these errors in the sample and also projects the error rate to the population, estimating an additional $45,000 in likely misstatements. Under AU-C 450, how should these amounts be classified?', '["Both the $6,200 and $45,000 are factual misstatements", "The $6,200 represents known misstatements and the $45,000 represents likely misstatements from sampling projection", "The entire $51,200 should be treated as projected misstatements", "The $6,200 are known misstatements and the $45,000 are judgmental misstatements"]'::jsonb, 3, 'AU-C 450.A4 distinguishes between factual misstatements (specific errors identified with certainty), projected misstatements (the auditor''s best estimate of misstatements in populations based on sampling), and judgmental misstatements (differences arising from management''s judgments). The $6,200 are factual/known; the $45,000 projection from sampling is a projected misstatement. Option D is incorrect because projected misstatements from sampling are not judgmental—they arise from statistical extrapolation, not management estimates.', 'medium', 2),

-- Q14: hard / L3 — Compensating controls mitigating a potential material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Energy Partners, the auditor identifies that the revenue recognition system lacks automated cutoff controls, allowing transactions to be recorded in incorrect periods. However, the controller performs a detailed monthly cutoff analysis reconciling shipping documents to recorded revenue within two business days of month-end. The analysis has been performed consistently for the past 12 months with no exceptions. The auditor should:', '["Classify the deficiency as a material weakness because automated controls are more reliable than manual compensating controls", "Disregard the deficiency entirely since the compensating control has operated effectively", "Evaluate whether the compensating control sufficiently reduces the likelihood and magnitude of potential misstatement to below the material weakness threshold", "Report both the original deficiency and the compensating control as separate significant deficiencies"]'::jsonb, 2, 'Under AU-C 265.A11, the auditor considers compensating controls when evaluating the severity of a deficiency. An effective compensating control that operates consistently can reduce the severity classification. The auditor must assess whether the compensating control sufficiently addresses the risk. Option A is incorrect because the standard does not automatically disqualify manual compensating controls; their effectiveness depends on consistent operation and appropriate design.', 'hard', 3),

-- Q15: easy / L1 — Auditor action after management corrects all misstatements
(1, 'Misstatements and Control Deficiencies', 'When management corrects all misstatements identified during the audit, the auditor is required to:', '["Inform those charged with governance that no misstatements were found", "Disclose the original misstatements in the auditor''s report", "Perform additional procedures to verify corrections were properly recorded", "Determine whether there are additional undetected misstatements indicated by the corrected ones"]'::jsonb, 3, 'AU-C 450.08 requires the auditor to determine whether the audit strategy and plan need revision when identified misstatements may indicate that additional misstatements exist. Even after management correction, the nature of the errors may signal systematic problems requiring further investigation. Option C is partially correct but incomplete—the primary obligation is to consider whether the identified misstatements indicate broader issues.', 'easy', 1),

-- Q16: hard / L4 — Evaluating sufficiency of management remediation for a repeat material weakness
(1, 'Misstatements and Control Deficiencies', 'Thornfield Industries received a material weakness communication in the prior year regarding inadequate review of journal entries. Management implemented a new review procedure mid-year, and the auditor tests the new control for the last six months. Three of 25 sampled entries lack evidence of review. Management asserts the control is now effective. In evaluating whether to report this as a continued material weakness, the auditor should primarily consider:', '["Whether management''s representation about control effectiveness is included in the management representation letter", "Whether the three exceptions represent a deviation rate that indicates the control is not operating effectively, combined with the limited period of operation", "Whether the prior-year material weakness should be considered remediated since management took corrective action", "Whether the three exceptions involved amounts above the clearly trivial threshold"]'::jsonb, 1, 'Under AU-C 265.A14, the auditor considers the period of operation and deviation rate when evaluating remediated controls. A 12% deviation rate (3/25) over only six months does not provide sufficient evidence of effective operation. The auditor should report the continued material weakness. Option C is incorrect because taking corrective action alone does not constitute remediation—the control must operate effectively for a sufficient period.', 'hard', 4),

-- Q17: medium / L2 — Automated control lacking exception handling as a control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Horizon Logistics, the auditor finds that the automated purchase order matching system correctly matches invoices to purchase orders but has no process for handling exceptions. When a mismatch occurs, the invoice is placed in a queue that no one monitors, resulting in unprocessed invoices accumulating for months. Under AU-C 265, this represents:', '["A control deficiency because the exception-handling process is inadequate, creating a risk of unrecorded liabilities", "An operational efficiency issue outside the scope of financial statement auditing", "A significant deficiency only if the unprocessed invoices exceed materiality individually", "An IT control matter that should be communicated to management as an informational item"]'::jsonb, 0, 'Under AU-C 265.A1, a control deficiency exists when the design or operation of a control does not allow management or employees to prevent or detect misstatements on a timely basis. An unmonitored exception queue creates risk of unrecorded liabilities. Option B is incorrect because unprocessed vendor invoices directly affect financial statement completeness, making this a financial reporting control deficiency rather than merely an operational matter.', 'medium', 2),

-- Q18: medium / L2 — Summary of uncorrected misstatements and management representation letter
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork for Ashford Biotech, the auditor prepares a summary of uncorrected misstatements totaling $62,000 against materiality of $250,000. Management reviews the summary and agrees the effects are immaterial. Under AU-C 450, the auditor should:', '["Accept management''s agreement and issue an unmodified opinion without further action", "Require management to adjust the financial statements for all items on the summary", "Disclose the uncorrected misstatements in the notes to the financial statements", "Request a written representation from management that the uncorrected misstatements are immaterial, both individually and in aggregate"]'::jsonb, 3, 'AU-C 450.14 requires the auditor to request a written representation from management that uncorrected misstatements are immaterial to the financial statements, individually and in the aggregate. This representation is included in the management representation letter. Option A is incorrect because management''s verbal agreement is insufficient—a written representation is required as part of the audit documentation.', 'medium', 2),

-- Q19: easy / L2 — Individually immaterial misstatements becoming material in aggregate
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakeview Community Hospital, the auditor identifies 15 separate misstatements, each ranging from $3,000 to $8,000, all understating expenses. Materiality is $100,000. Under AU-C 450, the auditor should:', '["Disregard the misstatements since each is clearly trivial relative to materiality", "Evaluate the aggregate effect of all 15 misstatements, considering their cumulative impact and one-directional nature", "Report each misstatement individually to those charged with governance", "Accept the misstatements without further evaluation because they are below 10% of materiality individually"]'::jsonb, 1, 'AU-C 450.06 requires the auditor to accumulate misstatements identified during the audit, other than those that are clearly trivial. The aggregate of 15 misstatements ($45,000–$120,000 range) may approach or exceed materiality, and their one-directional nature suggests possible bias. Option A is incorrect because individual immateriality does not eliminate the need to evaluate aggregate effects.', 'easy', 2),

-- Q20: medium / L2 — Unauthorized person performing key reconciliation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ironbridge Manufacturing, the auditor discovers that the monthly bank reconciliation has been performed by the same employee who records cash receipts for the past eight months due to staffing shortages. The reconciliations appear accurate. Under AU-C 265, the auditor should classify this as:', '["An operational staffing issue that does not affect the financial statement audit", "An insignificant deficiency because the reconciliations have been performed accurately", "A control deficiency related to inadequate segregation of duties that must be evaluated for severity based on magnitude and likelihood of potential misstatement", "A finding that should be communicated only in the management letter, not as a control deficiency"]'::jsonb, 2, 'Under AU-C 265.A1, a control deficiency exists when a control is not properly designed or operating to prevent or detect misstatements. Having the same person record cash receipts and reconcile the bank account eliminates a key detective control. Option B is incorrect because the accuracy of past reconciliations does not eliminate the underlying segregation of duties deficiency—the risk of future misstatement remains.', 'medium', 2),

-- Q21: easy / L1 — Definition of reasonable possibility in AU-C 265
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, "reasonable possibility" in the context of evaluating whether a control deficiency is a material weakness means:', '["A probability of occurrence greater than 75%", "A likelihood that is certain or nearly certain to occur", "A mathematical probability exceeding 50%", "More than a remote likelihood that a misstatement could occur"]'::jsonb, 3, 'AU-C 265.A7 clarifies that "reasonable possibility" exists when the likelihood of an event is either reasonably possible or probable—essentially, more than remote. This is a lower threshold than "more likely than not." Option C is incorrect because reasonable possibility does not require a greater-than-50% mathematical probability; it simply requires more than a remote chance.', 'easy', 1),

-- Q22: medium / L2 — Prior-period uncorrected misstatements affecting current-year evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Foxglove Apparel, the auditor notes that $35,000 in uncorrected misstatements from the prior year''s audit have a continuing effect on the current year''s financial statements. Current-year identified misstatements total $28,000. Materiality is $75,000. Under AU-C 450, the auditor should:', '["Ignore the prior-year misstatements since they were already evaluated and accepted", "Consider only the $28,000 in current-year misstatements for the evaluation", "Request management correct only the prior-year amounts since they are larger", "Evaluate the combined effect of both prior-year carryover misstatements and current-year misstatements on the current financial statements"]'::jsonb, 1, 'AU-C 450.06 requires the auditor to consider the effect of uncorrected misstatements from prior periods that have a material effect on the current period''s financial statements. The combined $63,000 ($35,000 + $28,000) approaches materiality of $75,000 and must be evaluated in aggregate. Option A is incorrect because prior-year uncorrected misstatements with continuing effects must be reconsidered in the current-year evaluation.', 'medium', 2),

-- Q23: medium / L3 — Revenue cutoff errors suggesting systematic control failure
(1, 'Misstatements and Control Deficiencies', 'While auditing Crestline Retail Partners, the auditor tests revenue cutoff for December and finds that 8 of 30 sampled transactions were recorded in the wrong period, always in the direction of accelerating revenue into the current period. Each error ranges from $4,000 to $12,000. The auditor should evaluate this finding as:', '["Evidence of a potential material weakness in revenue cutoff controls combined with a potential indicator of management bias requiring expanded procedures", "Individual misstatements that should be corrected but do not indicate a systematic problem", "A sampling anomaly that can be addressed by increasing sample size in the next audit", "An immaterial pattern since each transaction is individually small relative to total revenue"]'::jsonb, 0, 'Under AU-C 265.A7 and AU-C 450.A22, the 27% error rate (8/30) in cutoff testing with a consistent directional bias toward overstating current-period revenue indicates both a control deficiency of potentially high severity and possible management bias. The auditor must evaluate the control deficiency''s severity and consider expanding substantive procedures. Option B is incorrect because the systematic one-directional nature of the errors strongly suggests a control design or operation failure rather than isolated incidents.', 'medium', 3),

-- Q24: hard / L4 — Audit response to pervasive control environment failure
(1, 'Misstatements and Control Deficiencies', 'During the audit of Heathrow Holdings, the auditor identifies three significant deficiencies: (1) the board audit committee lacks financial expertise, (2) management has overridden monthly closing procedures twice during the year, and (3) the entity has no formal risk assessment process. Individually, each deficiency falls below the material weakness threshold. The auditor should:', '["Report each as a separate significant deficiency since none individually qualifies as a material weakness", "Evaluate whether the combination of these entity-level control deficiencies collectively constitutes a material weakness in the overall control environment", "Defer reporting until the next audit to determine if the deficiencies persist", "Communicate the deficiencies verbally to management without formal written communication"]'::jsonb, 1, 'Under AU-C 265.A10, the auditor considers whether individually insignificant deficiencies in combination represent a significant deficiency or material weakness. Entity-level control failures—governance gaps, management override, and absence of risk assessment—undermine the entire control environment and may collectively constitute a material weakness. Option A is incorrect because the standard explicitly requires the auditor to consider the combined effect of deficiencies rather than evaluating them only in isolation.', 'hard', 4),

-- Q25: hard / L4 — Communication obligations when management disagrees with material weakness classification
(1, 'Misstatements and Control Deficiencies', 'After identifying a material weakness in inventory controls at Ridgeway Distribution, the CEO and CFO insist the deficiency is only a significant deficiency and refuse to include it as a material weakness in management''s representation letter. The auditor has thoroughly documented the analysis supporting the material weakness classification. The auditor should:', '["Downgrade the classification to significant deficiency based on management''s operational knowledge", "Accept a modified representation letter noting management''s disagreement", "Communicate the material weakness in writing to those charged with governance regardless of management''s disagreement, as the classification is the auditor''s professional judgment", "Withdraw from the engagement due to the disagreement with management"]'::jsonb, 2, 'Under AU-C 265.09, the auditor is required to communicate material weaknesses in writing to those charged with governance. The classification of control deficiency severity is the auditor''s professional judgment, not management''s. Management''s disagreement does not change the auditor''s obligation or classification. Option A is incorrect because the auditor must exercise independent judgment in classifying deficiency severity and cannot defer to management''s preferred characterization.', 'hard', 4),

-- Q26: hard / L4 — Interaction between entity-level and transaction-level control deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Global Enterprises, the auditor finds that management''s tone regarding financial reporting integrity is weak—the CEO has publicly pressured staff to "make the numbers work." Additionally, the auditor identifies a moderate transaction-level deficiency in the accounts payable matching process. When evaluating the severity of the accounts payable deficiency, the auditor should:', '["Evaluate the accounts payable deficiency independently without considering entity-level factors", "Consider the deficiency as automatically remediated if compensating transaction-level controls exist", "Report only the entity-level concern and omit the accounts payable deficiency from the communication", "Consider how the weak tone at the top increases the likelihood that the transaction-level deficiency could result in a material misstatement"]'::jsonb, 3, 'Under AU-C 265.A9, entity-level control weaknesses such as a poor tone at the top affect the operating effectiveness of transaction-level controls. Management pressure to manipulate results increases the likelihood that process-level deficiencies will result in actual misstatements, potentially elevating their severity classification. Option A is incorrect because AU-C 265 requires a holistic evaluation where entity-level factors influence the assessed severity of transaction-level deficiencies.', 'hard', 4),

-- Q27: medium / L3 — Reclassifying a previously reported significant deficiency based on new information
(1, 'Misstatements and Control Deficiencies', 'In the prior year, the auditor of Birchfield Energy reported a significant deficiency in the fixed asset capitalization process. During the current-year audit, the auditor discovers that the same deficiency resulted in $340,000 of improper capitalizations, with materiality set at $400,000. The deficiency remains unremediated. The auditor should:', '["Maintain the significant deficiency classification since the deficiency was previously classified", "Reclassify the deficiency as a material weakness based on the current-year evidence that the deficiency nearly resulted in a material misstatement", "Report the deficiency as remediated since the $340,000 was identified and can be corrected", "Reduce the classification to a control deficiency because the amount was detected during the audit"]'::jsonb, 1, 'Under AU-C 265.A13, the auditor reevaluates the severity of previously communicated deficiencies each year based on current facts. The $340,000 actual misstatement (85% of materiality) demonstrates that the deficiency can result in material misstatement, satisfying the magnitude criterion for a material weakness. Option A is incorrect because the prior-year classification does not bind the current-year evaluation—new evidence changes the assessment.', 'medium', 3),

-- Q28: easy / L1 — Purpose of the summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'The auditor''s "summary of uncorrected misstatements" prepared under AU-C 450 serves primarily to:', '["Document all errors for regulatory reporting to the PCAOB", "Provide a record of misstatements that management has not corrected, for evaluating their aggregate effect on the financial statements", "Replace the need for a management representation letter regarding misstatements", "Identify individual misstatements that require disclosure in the notes to the financial statements"]'::jsonb, 0, 'AU-C 450.06 requires the auditor to accumulate identified misstatements during the audit. The summary enables the auditor to evaluate whether uncorrected misstatements, individually or in aggregate, are material to the financial statements. Option C is incorrect because the summary supplements rather than replaces the management representation letter—management must still represent that uncorrected misstatements are immaterial.', 'easy', 1),

-- Q29: easy / L1 — Required content of written communication about significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the auditor''s written communication of significant deficiencies and material weaknesses must include:', '["A guarantee that no other deficiencies exist beyond those communicated", "A detailed remediation plan with specific timelines for correcting each deficiency", "A description of the deficiencies and an explanation of their potential effects", "A comparison of the entity''s controls to industry best practices"]'::jsonb, 2, 'AU-C 265.11 requires the written communication to include a description of the deficiencies and an explanation of their potential effects. The communication must also state that the purpose was not to identify all deficiencies. Option A is incorrect because the auditor specifically cannot provide assurance that all deficiencies have been identified—this caveat is a required element of the communication.', 'easy', 1),

-- Q30: medium / L3 — Impact of accounting staff turnover on control deficiency assessment
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Aerospace, the auditor learns that three of five accounting staff members resigned mid-year and were replaced by temporary workers with limited industry experience. The journal entry review, account reconciliation, and financial close processes are all performed by these temporary staff. The auditor should evaluate this situation as:', '["An operational staffing concern that falls outside the scope of control deficiency evaluation", "A temporary inconvenience that will resolve itself when permanent staff are hired", "A human resources matter that should be communicated in the management letter only", "A potential control deficiency affecting the competence element of the control environment, requiring assessment of its impact on financial reporting reliability"]'::jsonb, 3, 'Under AU-C 265.A1 and the COSO framework, the competence of personnel performing control activities is a fundamental component of the control environment. Significant turnover in accounting staff replaced by less experienced temporary workers affects the design and operating effectiveness of multiple controls. Option A is incorrect because staffing changes that impact the competence of personnel performing financial reporting controls are directly relevant to the auditor''s control deficiency evaluation.', 'medium', 3)
;

COMMIT;
